  /**
   * Returns the hash code of this object.
   */
  @Override
  public int hashCode() {
    if (value == null) {
      return 31;
    }
    // Using recommended hashing algorithm from Effective Java for longs and doubles
    if (isIntegral(this)) {
      long value = getAsNumber().longValue();
      return (int) (value ^ (value >>> 32));
    }
    if (value instanceof Number) {
      long value = Double.doubleToLongBits(getAsNumber().doubleValue());
      return (int) (value ^ (value >>> 32));
    }
    return value.hashCode();
  }

  /**
   * Returns whether the other object is equal to this. This method only considers
   * the other object to be equal if it is an instance of {@code JsonPrimitive} and
   * has an equal value.
   */
  @Override
  public boolean equals(Object obj) {
    if (this == obj) {
      return true;
    }
    if (obj == null || getClass() != obj.getClass()) {
      return false;
    }
    JsonPrimitive other = (JsonPrimitive)obj;
    if (value == null) {
      return other.value == null;
    }
    if (isIntegral(this) && isIntegral(other)) {
      return getAsNumber().longValue() == other.getAsNumber().longValue();
    }
    if (value instanceof Number && other.value instanceof Number) {
      double a = getAsNumber().doubleValue();
      // Java standard types other than double return true for two NaN. So, need
      // special handling for double.
      double b = other.getAsNumber().doubleValue();
      return a == b || (Double.isNaN(a) && Double.isNaN(b));
    }
    return value.equals(other.value);
  }

  /**
   * Returns true if the specified number is an integral type
   * (Long, Integer, Short, Byte, BigInteger)
   */
  private static boolean isIntegral(JsonPrimitive primitive) {
    if (primitive.value instanceof Number) {
      Number number = (Number) primitive.value;
      return number instanceof BigInteger || number instanceof Long || number instanceof Integer
          || number instanceof Short || number instanceof Byte;
    }
    return false;
  }

  /**
   * Writes {@code element} to {@code out}. Primitive values reuse this instance's
   * encoded value while arrays and objects are written from their tree structure.
   */
  public void writeJson(JsonWriter out, JsonElement element) throws IOException {
    if (out instanceof JsonTreeWriter) {
      JsonTreeWriter treeWriter = (JsonTreeWriter) out;
      if (element == null || element.isJsonNull()) {
        if (treeWriter.pendingName != null) {
          if (treeWriter.getSerializeNulls()) {
            JsonObject object = (JsonObject) treeWriter.stack.get(treeWriter.stack.size() - 1);
            object.add(treeWriter.pendingName, JsonNull.INSTANCE);
          }
          treeWriter.pendingName = null;
        } else if (treeWriter.stack.isEmpty()) {
          treeWriter.product = JsonNull.INSTANCE;
        } else {
          JsonElement top = treeWriter.stack.get(treeWriter.stack.size() - 1);
          if (top instanceof JsonArray) {
            ((JsonArray) top).add(JsonNull.INSTANCE);
          } else {
            throw new IllegalStateException();
          }
        }
        return;
      }

      if (element.isJsonPrimitive()) {
        JsonPrimitive primitive = (JsonPrimitive) element;
        Object encoded = primitive == this ? this.value : primitive.value;
        JsonPrimitive encodedPrimitive;
        if (encoded instanceof Number) {
          Number number = (Number) encoded;
          if (number instanceof LazilyParsedNumber) {
            String raw = number.toString();
            if (!treeWriter.isLenient()) {
              double asDouble = Double.parseDouble(raw);
              if (Double.isNaN(asDouble) || Double.isInfinite(asDouble)) {
                throw new IllegalArgumentException("JSON forbids NaN and infinities: " + number);
              }
            }
          } else if (!treeWriter.isLenient()) {
            double asDouble = number.doubleValue();
            if (Double.isNaN(asDouble) || Double.isInfinite(asDouble)) {
              throw new IllegalArgumentException("JSON forbids NaN and infinities: " + number);
            }
          }
          encodedPrimitive = new JsonPrimitive(number);
        } else if (encoded instanceof Boolean) {
          encodedPrimitive = new JsonPrimitive((Boolean) encoded);
        } else {
          encodedPrimitive = new JsonPrimitive(primitive.getAsString());
        }
        if (treeWriter.pendingName != null) {
          if (!encodedPrimitive.isJsonNull() || treeWriter.getSerializeNulls()) {
            JsonObject object = (JsonObject) treeWriter.stack.get(treeWriter.stack.size() - 1);
            object.add(treeWriter.pendingName, encodedPrimitive);
          }
          treeWriter.pendingName = null;
        } else if (treeWriter.stack.isEmpty()) {
          treeWriter.product = encodedPrimitive;
        } else {
          JsonElement top = treeWriter.stack.get(treeWriter.stack.size() - 1);
          if (top instanceof JsonArray) {
            ((JsonArray) top).add(encodedPrimitive);
          } else {
            throw new IllegalStateException();
          }
        }
        return;
      }

      if (element.isJsonArray()) {
        JsonArray array = (JsonArray) element;
        JsonArray copy = new JsonArray();
        if (treeWriter.pendingName != null) {
          JsonObject object = (JsonObject) treeWriter.stack.get(treeWriter.stack.size() - 1);
          object.add(treeWriter.pendingName, copy);
          treeWriter.pendingName = null;
        } else if (treeWriter.stack.isEmpty()) {
          treeWriter.product = copy;
        } else {
          JsonElement top = treeWriter.stack.get(treeWriter.stack.size() - 1);
          if (top instanceof JsonArray) {
            ((JsonArray) top).add(copy);
          } else {
            throw new IllegalStateException();
          }
        }
        treeWriter.stack.add(copy);
        for (int i = 0, size = array.elements.size(); i < size; i++) {
          writeJson(treeWriter, array.elements.get(i));
        }
        if (treeWriter.stack.isEmpty() || treeWriter.pendingName != null) {
          throw new IllegalStateException();
        }
        JsonElement ended = treeWriter.stack.get(treeWriter.stack.size() - 1);
        if (ended instanceof JsonArray) {
          treeWriter.stack.remove(treeWriter.stack.size() - 1);
          return;
        }
        throw new IllegalStateException();
      }

      if (element.isJsonObject()) {
        JsonObject object = (JsonObject) element;
        LinkedTreeMap<String, JsonElement> members = object.members;
        JsonObject copy = new JsonObject();
        if (treeWriter.pendingName != null) {
          JsonObject parent = (JsonObject) treeWriter.stack.get(treeWriter.stack.size() - 1);
          parent.add(treeWriter.pendingName, copy);
          treeWriter.pendingName = null;
        } else if (treeWriter.stack.isEmpty()) {
          treeWriter.product = copy;
        } else {
          JsonElement top = treeWriter.stack.get(treeWriter.stack.size() - 1);
          if (top instanceof JsonArray) {
            ((JsonArray) top).add(copy);
          } else {
            throw new IllegalStateException();
          }
        }
        treeWriter.stack.add(copy);
        if (members.size() != 0) {
          for (Map.Entry<String, JsonElement> entry : members.entrySet()) {
            if (treeWriter.stack.isEmpty() || treeWriter.pendingName != null) {
              throw new IllegalStateException();
            }
            JsonElement parent = treeWriter.stack.get(treeWriter.stack.size() - 1);
            if (!(parent instanceof JsonObject)) {
              throw new IllegalStateException();
            }
            treeWriter.pendingName = entry.getKey();
            writeJson(treeWriter, entry.getValue());
          }
        }
        if (treeWriter.stack.isEmpty() || treeWriter.pendingName != null) {
          throw new IllegalStateException();
        }
        JsonElement ended = treeWriter.stack.get(treeWriter.stack.size() - 1);
        if (ended instanceof JsonObject) {
          treeWriter.stack.remove(treeWriter.stack.size() - 1);
          return;
        }
        throw new IllegalStateException();
      }

      throw new IllegalArgumentException("Couldn't write " + element.getClass());
    }

    if (out.getClass() != JsonWriter.class) {
      if (element == null || element.isJsonNull()) {
        out.nullValue();
      } else if (element.isJsonPrimitive()) {
        JsonPrimitive primitive = (JsonPrimitive) element;
        Object encoded = primitive == this ? this.value : primitive.value;
        if (encoded instanceof Number || primitive.isNumber()) {
          Number number = encoded instanceof Number ? (Number) encoded : primitive.getAsNumber();
          if (number instanceof LazilyParsedNumber) {
            String raw = number.toString();
            if (!out.isLenient()
                && (raw.equals("-Infinity") || raw.equals("Infinity") || raw.equals("NaN"))) {
              throw new IllegalArgumentException("Numeric values must be finite, but was " + raw);
            }
          }
          out.value(number);
        } else if (encoded instanceof Boolean || primitive.isBoolean()) {
          out.value(primitive.getAsBoolean());
        } else {
          out.value(primitive.getAsString());
        }
      } else if (element.isJsonArray()) {
        JsonArray array = (JsonArray) element;
        out.beginArray();
        for (int i = 0, size = array.elements.size(); i < size; i++) {
          writeJson(out, array.elements.get(i));
        }
        out.endArray();
      } else if (element.isJsonObject()) {
        JsonObject object = (JsonObject) element;
        LinkedTreeMap<String, JsonElement> members = object.members;
        out.beginObject();
        if (members.size() != 0) {
          for (Map.Entry<String, JsonElement> entry : members.entrySet()) {
            out.name(entry.getKey());
            writeJson(out, entry.getValue());
          }
        }
        out.endObject();
      } else {
        throw new IllegalArgumentException("Couldn't write " + element.getClass());
      }
      return;
    }

    if (out.stackSize == 0) {
      throw new IllegalStateException("JsonWriter is closed.");
    }

    if (element == null || element.isJsonNull()) {
      if (out.deferredName != null && !out.getSerializeNulls()) {
        out.deferredName = null;
        return;
      }
      out.nullValue();
      return;
    }

    if (element.isJsonPrimitive()) {
      JsonPrimitive primitive = (JsonPrimitive) element;
      Object encoded = primitive == this ? this.value : primitive.value;
      if (encoded instanceof Number || primitive.isNumber()) {
        Number number = encoded instanceof Number ? (Number) encoded : primitive.getAsNumber();
        if (number instanceof LazilyParsedNumber) {
          String raw = number.toString();
          if (!out.isLenient()
              && (raw.equals("-Infinity") || raw.equals("Infinity") || raw.equals("NaN"))) {
            throw new IllegalArgumentException("Numeric values must be finite, but was " + raw);
          }
        }
        out.value(number);
        return;
      }
      if (encoded instanceof Boolean || primitive.isBoolean()) {
        out.value(primitive.getAsBoolean());
        return;
      }
      out.value(primitive.getAsString());
      return;
    }

    if (element.isJsonArray()) {
      JsonArray array = (JsonArray) element;
      out.beginArray();
      for (int i = 0, size = array.elements.size(); i < size; i++) {
        writeJson(out, array.elements.get(i));
      }
      out.endArray();
      return;
    }

    if (element.isJsonObject()) {
      JsonObject object = (JsonObject) element;
      LinkedTreeMap<String, JsonElement> members = object.members;
      out.beginObject();
      if (members.size() != 0) {
        for (Map.Entry<String, JsonElement> entry : members.entrySet()) {
          out.name(entry.getKey());
          writeJson(out, entry.getValue());
        }
      }
      out.endObject();
      return;
    }

    throw new IllegalArgumentException("Couldn't write " + element.getClass());
  }
